export const getSubmitWeixinVerifyCodeUrl = (login: string) => {
  return `https://assistant.leaflow.cloud/api/v1/weixin-logins/${encodeURIComponent(String(login))}:verifyCode`;
};

/**
 * For when WeChat asks for an SMS or device code after the scan. The person who started the login gets that code on their own phone.
 * @summary Submit a login verification code
 */
export const submitWeixinVerifyCode = async (
  login: string,
  verifyCodeRequestBody: VerifyCodeRequestBody,
  options?: RequestInit,
  fetchFn?: typeof globalThis.fetch,
): Promise<submitWeixinVerifyCodeResponse> => {
  const getHeaders = (
    h?: NonNullable<RequestInit["headers"]>,
  ): Record<string, string | readonly string[]> => {
    if (!h) return {};
    if (h instanceof Headers) return Object.fromEntries(h.entries());
    if (Symbol.iterator in h) {
      return Object.fromEntries(
        Array.from(
          h as Iterable<Iterable<string>>,
          (entry) => Array.from(entry) as [string, string],
        ),
      );
    }
    const headers: Record<string, string | readonly string[]> = {};
    for (const [name, value] of Object.entries<string | readonly string[] | undefined>(h)) {
      if (value !== undefined) headers[name] = value;
    }
    return headers;
  };
  const res = await (fetchFn ?? fetch)(getSubmitWeixinVerifyCodeUrl(login), {
    ...options,
    method: "POST",
    headers: { "Content-Type": "application/json", ...getHeaders(options?.headers) },
    body: JSON.stringify(verifyCodeRequestBody),
  });

  const body = [204, 205, 304].includes(res.status) ? null : await res.text();

  const data: submitWeixinVerifyCodeResponse["data"] = body ? JSON.parse(body) : {};
  return { data, status: res.status, headers: res.headers } as submitWeixinVerifyCodeResponse;
};
